import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int q = (int) nextLong();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String s = next();
            int zeros = 0;
            for (int j = 0; j < s.length(); j++)
                if (s.charAt(j) == '0') zeros++;
            out.append(s.charAt(0) == '1' && zeros >= 2 && zeros % 2 == 0 ? "True" : "False").append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"io"
	"os"
	"strings"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := int(nextInt())
	var out strings.Builder
	for i := 0; i < q; i++ {
		s := nextToken()
		zeros := strings.Count(s, "0")
		if s[0] == '1' && zeros >= 2 && zeros%2 == 0 {
			out.WriteString("True\n")
		} else {
			out.WriteString("False\n")
		}
	}
	os.Stdout.WriteString(out.String())
}
